# simulator, benchmark
xm <- function(S, BAL, BA, SDI, sm, byi, pl) cbind(1, log(S + 1), S, BAL / pmax(BA, 1e-6) * SDI / sm, log(byi), pl)
sim <- function(dbh, ht, ex, byi, pl, years, sm, bg, bm) { out <- vector("list", years + 1)
  for (y in 0:years) { s <- koa_stand(dbh, ht, ex); out[[y + 1]] <- data.table(year = y, BA = s$BA, TPH = s$TPH, QMD = s$QMD, SDI = s$SDI, RD = s$SDI / sm, HT = s$HT); if (y == years) break
    bal <- koa_bal(dbh, s$ba); rd <- s$SDI / sm; g <- as.numeric(exp(xm(dbh, bal, s$BA, s$SDI, sm, byi, pl) %*% bg))
    pm <- 1 - exp(-exp(bm[["(Intercept)"]] + bm[["ld"]] * log(dbh + 1) + bm[["dbh_m"]] * dbh + bm[["I(dbh_m^2)"]] * dbh^2 + bm[["BAL"]] * bal + bm[["lrd"]] * log(max(rd, 0.001)) + bm[["lbyi"]] * log(byi) + bm[["planted"]] * pl))
    ht <- ht + koa_height(dbh + g, cf) - koa_height(dbh, cf); dbh <- dbh + g; ex <- ex * (1 - pm) }
  rbindlist(out) }
startv <- tr[Status == "live" & !is.na(DBH) & DBH > 0, .(n = .N), by = .(pid, Measure)][n >= 5][, .SD[which.min(Measure)], by = pid]
benchf <- function(SMv, bg, bm) rbindlist(lapply(seq_len(nrow(startv)), function(i) { p <- startv$pid[i]; m0 <- startv$Measure[i]; L <- tr[pid == p & Measure == m0 & Status == "live" & !is.na(DBH) & DBH > 0]; pl <- L$planted[1]; byi <- L$BYI[1]
  L[is.na(HT) | HT < 1.37, HT := koa_height(DBH, cf)]; later <- sort(unique(tr[pid == p & Measure > m0, Measure])); if (nrow(f$srep[pid == p & Measure >= m0])) later <- later[later <= min(f$srep[pid == p & Measure >= m0, Measure])]
  if (!length(later)) return(NULL); z <- sim(L$DBH, L$HT, L$EXPF_c, byi, pl, max(later) - m0, SMv[[p]], bg, bm)
  rbindlist(lapply(later, function(m1) { ob <- merge(tr[pid == p & Measure == m1 & uid %in% L$uid & Status == "live", .(uid, DBH_c)], L[, .(uid, EXPF_c)], by = "uid"); if (!nrow(ob)) return(NULL); zz <- z[year == m1 - m0]
    data.table(pid = p, planted = pl, byi = byi, h = m1 - m0, o_surv = sum(ob$EXPF_c) / sum(L$EXPF_c), p_surv = zz$TPH / sum(L$EXPF_c), o_qmd = sqrt(sum(ob$DBH_c^2 * ob$EXPF_c) / sum(ob$EXPF_c)), p_qmd = zz$QMD, o_ba = sum(0.00007854 * ob$DBH_c^2 * ob$EXPF_c), p_ba = zz$BA) })) }))
s2 <- function(fm, d) lm(fm, data = d, weights = w); o2 <- rep(NA_real_, nrow(P)); for (k in sort(unique(P$fold))) o2[P$fold == k] <- predict(s2(ls ~ lbyi + planted, M[fold != k]), P[fold == k])
S742 <- setNames(rep(POP, nrow(P)), P$pid); SOWN <- setNames(ifelse(is.na(P$smax), POP, P$smax), P$pid); SBYI <- setNames(exp(o2), P$pid)
BB <- parallel::mclapply(list(A = list(S742, bg0, bm0), B = list(S742, RF$pop742$bg, RF$pop742$bm), D = list(SBYI, RF$s2_byi_origin$bg, RF$s2_byi_origin$bm), own = list(SOWN, bg0, bm0)), function(a) benchf(a[[1]], a[[2]], a[[3]]), mc.cores = 4)
rm1 <- function(b, v) sqrt(mean((b[[paste0("o_", v)]] - b[[paste0("p_", v)]])^2)); cat("\n(4) benchmark RMSE: A = 742 with current equations, B = 742 with equations refitted at 742, D = f(BYI, origin) refitted with out-of-fold SDImax, own = each plot's own value\n")
print(rbindlist(lapply(names(BB), function(n) data.table(set = n, surv = round(rm1(BB[[n]], "surv"), 3), qmd = round(rm1(BB[[n]], "qmd"), 2), ba = round(rm1(BB[[n]], "ba"), 2), ba_h10 = round(rm1(BB[[n]][h >= 10], "ba"), 2)))))
stopifnot(all(sapply(BB, function(b) identical(b$pid, BB$A$pid) && identical(b$h, BB$A$h)))); pl <- split(seq_len(nrow(BB$A)), BB$A$pid); nm <- names(pl)
pd <- function(x, y, v, sub = NULL) { d <- replicate(2000, { ix <- unlist(pl[sample(nm, length(nm), TRUE)], use.names = FALSE); if (!is.null(sub)) ix <- ix[BB$A$h[ix] >= sub]; rm1(BB[[x]][ix], v) - rm1(BB[[y]][ix], v) }); round(c(diff = rm1(if (is.null(sub)) BB[[x]] else BB[[x]][h >= sub], v) - rm1(if (is.null(sub)) BB[[y]] else BB[[y]][h >= sub], v), quantile(d, c(.025, .975), na.rm = TRUE)), 3) }
cat("paired plot-cluster bootstrap (2,000) of the difference in RMSE, with 95% interval:\n"); for (cmp in list(c("B", "A"), c("D", "B"), c("D", "A"), c("own", "B"))) for (v in c("ba", "surv", "qmd")) cat(sprintf("  %s minus %s, %-4s all horizons: %s ; horizons of 10 yr or more: %s\n", cmp[1], cmp[2], v, paste(pd(cmp[1], cmp[2], v), collapse = " "), paste(pd(cmp[1], cmp[2], v, 10), collapse = " ")))
# (5) do the residuals under B want a site-varying SDImax?
l <- BB$B[, .SD[which.max(h)], by = pid]; l[, `:=`(lr_ba = log(o_ba / p_ba), lr_surv = o_surv - p_surv, lbyi = log(byi))]; l <- merge(l, P[, .(pid, ls)], by = "pid", all.x = TRUE)
cat("\n(5) residuals under B at each plot's longest horizon (55 plots): ln(observed/projected basal area) and observed minus projected survival, regressed on ln(BYI) and origin; then on ln(own SDImax / 742)\n")
for (y in c("lr_ba", "lr_surv")) { m <- lm(as.formula(paste(y, "~ lbyi + planted")), l); cat(" ", y, "~ ln(BYI) + planted:", paste(names(coef(m)), sprintf("%.3f (%.3f)", coef(m), sqrt(diag(vcov(m)))), collapse = "; "), sprintf(" R2 %.3f\n", summary(m)$r.squared)); m <- lm(as.formula(paste(y, "~ I(ls - log(742))")), l[!is.na(ls)]); cat(" ", y, "~ ln(own SDImax / 742):", paste(sprintf("%.3f (%.3f)", coef(m), sqrt(diag(vcov(m)))), collapse = "; "), sprintf(" R2 %.3f, plots %d\n", summary(m)$r.squared, nrow(l[!is.na(ls)]))) }
