ww <- dcast(W, set + age ~ byi, value.var = "BA"); cat("first age at which basal area is not ordered by site class:\n"); print(ww[, .(first = { o <- which(!(`120` <= `230` + 1e-9 & `230` <= `340` + 1e-9 & `340` <= `450` + 1e-9)); if (length(o)) age[o[1]] else NA_integer_ }), by = set])
